(function(){
var container=htmlNode.querySelector('#pbi-logs-dashboard');
if(!container)return;
function escapeHTML(v){return String(v==null?'':v).replace(/[&<>]/g,function(c){return c==='&'?'&amp;':(c==='<'?'&lt;':'&gt;');});}
function valuesToArray(values){if(!values)return[];if(Array.isArray(values))return values;if(typeof values.toArray==='function')return values.toArray();var len=values.length||values.size||(values.buffer?values.buffer.length:0)||0;var out=[];for(var i=0;i<len;i++){out.push(typeof values.get==='function'?values.get(i):values[i]);}return out;}
function toNumber(v){if(v===null||v===undefined||v==='')return null;var n=Number(v);return Number.isFinite(n)?n:null;}
function toTimestamp(v){if(v instanceof Date)return v.getTime();if(typeof v==='number')return v;var p=new Date(v).getTime();return Number.isFinite(p)?p:null;}
function formatTime(v){if(!Number.isFinite(v))return '--';var d=new Date(v);var dd=String(d.getDate()).padStart(2,'0');var mm=String(d.getMonth()+1).padStart(2,'0');var hh=String(d.getHours()).padStart(2,'0');var mi=String(d.getMinutes()).padStart(2,'0');return dd+'/'+mm+' '+hh+':'+mi;}
function frameLast(frame){try{var f=(frame&&frame.fields)||[];for(var fi=1;fi<f.length;fi++){var vals=valuesToArray(f[fi].values);for(var i=vals.length-1;i>=0;i--){var n=toNumber(vals[i]);if(n!==null)return n;}}return 0;}catch(e){return 0;}}
function pct(part,total){return total>0?Math.max(0,Math.min(100,(part/total)*100)):0;}
function findTimeField(fields){for(var i=0;i<fields.length;i++){if(fields[i].type==='time'||/^time$/i.test(fields[i].name||''))return fields[i];}return null;}
function readTemporal(frame){var fields=(frame&&frame.fields)||[];var timeField=findTimeField(fields);if(!timeField)return[];var times=valuesToArray(timeField.values).map(toTimestamp);var points=[];fields.forEach(function(field){if(field===timeField)return;var vals=valuesToArray(field.values);vals.forEach(function(raw,idx){var t=times[idx];var v=toNumber(raw);if(Number.isFinite(t)&&Number.isFinite(v)&&v>0)points.push({time:t,value:v});});});points.sort(function(a,b){return a.time-b.time;});return points;}
function scaleToTotal(points,total,minTime,maxTime){var exact=Number(total)||0;var sum=points.reduce(function(s,p){return s+p.value;},0);var out=points.slice();if(out.length&&exact>0&&sum>0){var factor=exact/sum;out=out.map(function(p){return{time:p.time,value:p.value*factor};});}
if(!out.length&&exact>0&&Number.isFinite(minTime)&&Number.isFinite(maxTime)){out=[{time:maxTime,value:exact,synthetic:true}];}
return out;}
var frames=(data&&data.series)||[];
if(!frames.length||data.state!=='Done'){container.innerHTML="<div class='pbi-root'><div class='pbi-empty'>Aguardando dados...</div></div>";return;}
var byRef={};
frames.forEach(function(fr){if(fr&&fr.refId)byRef[fr.refId]=fr;});
var normalCount=Math.round(frameLast(byRef.N));
var warnCount=Math.round(frameLast(byRef.W));
var critCount=Math.round(frameLast(byRef.C));
var totalCount=Math.round(frameLast(byRef.X));
var rawNormal=readTemporal(byRef.TN);
var rawWarn=readTemporal(byRef.TW);
var rawCrit=readTemporal(byRef.TC);
var allTimes=[];
[rawNormal,rawWarn,rawCrit].forEach(function(arr){arr.forEach(function(p){allTimes.push(p.time);});});
var minTime=allTimes.length?Math.min.apply(null,allTimes):Date.now()-3600000;
var maxTime=allTimes.length?Math.max.apply(null,allTimes):Date.now();
var series=[
{key:'normal',label:'Normal',color:'#22c55e',total:normalCount,points:scaleToTotal(rawNormal,normalCount,minTime,maxTime)},
{key:'atencao',label:'Atencao',color:'#facc15',total:warnCount,points:scaleToTotal(rawWarn,warnCount,minTime,maxTime)},
{key:'critico',label:'Critico',color:'#ef4444',total:critCount,points:scaleToTotal(rawCrit,critCount,minTime,maxTime)}
];
var normalPct=pct(normalCount,totalCount),warnPct=pct(warnCount,totalCount),critPct=pct(critCount,totalCount);
function icon(name){var map={chart:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.3' stroke-linecap='round' stroke-linejoin='round'><path d='M3 3v18h18'/><path d='M7 15v3'/><path d='M12 10v8'/><path d='M17 6v12'/></svg>",bulb:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><path d='M9 18h6'/><path d='M10 22h4'/><path d='M8.5 14.5a6 6 0 1 1 7 0c-.8.7-1.2 1.5-1.4 2.5H9.9c-.2-1-.6-1.8-1.4-2.5Z'/></svg>",info:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.3' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='9'/><path d='M12 11v5'/><path d='M12 8h.01'/></svg>",ok:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.5' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='9'/><path d='m8.5 12.5 2.3 2.3 4.9-5.4'/></svg>",warn:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.3' stroke-linecap='round' stroke-linejoin='round'><path d='M12 3 2.8 19a2 2 0 0 0 1.7 3h15a2 2 0 0 0 1.7-3L12 3Z'/><path d='M12 9v5'/><path d='M12 18h.01'/></svg>",bad:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.4' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='9'/><path d='M12 7v6'/><path d='M12 17h.01'/></svg>"};return"<span class='svg-icon' aria-hidden='true'>"+(map[name]||map.info)+"</span>";}
function renderGauge(iconName,label,ringColorVar,value,count,statusLevel,statusLabel,hint,drill){return "<article class='pbi-gauge-card' data-drill='"+(drill||'')+"' title='Clique para filtrar por severidade' style='--color:var("+ringColorVar+");'><div class='pbi-gauge' style='--value:"+value.toFixed(0)+";--color:var("+ringColorVar+");'><span class='pbi-gauge-value'>"+value.toFixed(0)+"%</span></div><div class='pbi-gauge-info'><div class='pbi-gauge-label'>"+icon(iconName)+" "+label+"</div><div class='pbi-gauge-title'>"+count.toLocaleString('pt-BR')+" logs</div><div class='pbi-gauge-status "+statusLevel+"'>"+statusLabel+"</div></div><button class='pbi-gauge-help' type='button' aria-label='Resumo "+label+"'>"+icon('info')+"</button><div class='pbi-gauge-tip'><strong>Resumo "+label+"</strong>"+hint+"<br><b>"+count.toLocaleString('pt-BR')+"</b> logs no periodo ("+value.toFixed(0)+"% do total).</div></article>";}
function buildChart(width,height){
var left=98,right=20,top=14,bottom=28,rowGap=14;
var plotW=width-left-right;
var rowH=(height-top-bottom-rowGap*2)/3;
if(rowH<34)rowH=34;
function xScale(t){return maxTime===minTime?left+plotW:left+((t-minTime)/(maxTime-minTime))*plotW;}
var grid='',bars='';
for(var j=0;j<=5;j++){var x=left+(plotW/5)*j;var t=minTime+((maxTime-minTime)/5)*j;var lbl=(formatTime(t).split(' ')[1])||'--';grid+="<line class='pbi-grid-line' x1='"+x+"' y1='"+top+"' x2='"+x+"' y2='"+(top+rowH*3+rowGap*2)+"'></line><text class='pbi-axis' x='"+(x-16)+"' y='"+(height-8)+"'>"+lbl+"</text>";}
series.forEach(function(s,idx){var y0=top+idx*(rowH+rowGap);var yBase=y0+rowH;var max=Math.max(1,Math.max.apply(null,s.points.map(function(p){return p.value;})),s.total>0?1:0);grid+="<line class='pbi-grid-line' x1='"+left+"' y1='"+yBase+"' x2='"+(width-right)+"' y2='"+yBase+"'></line><text class='pbi-axis-y' x='12' y='"+(y0+16)+"' style='fill:"+s.color+"'>"+s.label+"</text><text class='pbi-axis-y' x='12' y='"+(y0+32)+"'>"+s.total.toLocaleString('pt-BR')+" logs</text><text class='pbi-axis-y' x='"+(left-8)+"' y='"+(y0+5)+"' text-anchor='end'>"+Math.round(max).toLocaleString('pt-BR')+"</text>";
var points=s.points;
if(!points.length)return;
var barW=Math.max(4,Math.min(18,plotW/Math.max(points.length,24)*0.72));
points.forEach(function(p){var h=Math.max(4,(p.value/max)*rowH);var x=xScale(p.time)-barW/2;var y=yBase-h;bars+="<rect x='"+x.toFixed(1)+"' y='"+y.toFixed(1)+"' width='"+barW.toFixed(1)+"' height='"+h.toFixed(1)+"' rx='2' fill='"+s.color+"' opacity='"+(p.synthetic?".98":".88")+"'><title>"+s.label+" - "+Math.round(p.value).toLocaleString('pt-BR')+" logs em "+formatTime(p.time)+"</title></rect>";});
});
return "<svg class='pbi-chart' viewBox='0 0 "+width+" "+height+"' style='overflow:visible;'>"+grid+bars+"</svg>";
}
function renderChart(){var wrap=container.querySelector('.pbi-chart-wrap');if(!wrap)return;var rect=wrap.getBoundingClientRect();var w=rect.width>0?rect.width:900,h=rect.height>0?rect.height:220;wrap.innerHTML=buildChart(w,h);}
var legendHtml=series.map(function(s){return "<span><i class='pbi-dot' style='background:"+s.color+"'></i> "+escapeHTML(s.label)+"</span>";}).join('');
var insightText=totalCount>0?"Normal: "+normalCount.toLocaleString('pt-BR')+", Atencao: "+warnCount.toLocaleString('pt-BR')+", Critico: "+critCount.toLocaleString('pt-BR')+".":"Nenhum log encontrado no periodo selecionado.";
var lastRefresh=formatTime(Date.now());
container.innerHTML="<div class='pbi-root'><header class='pbi-header'><div class='pbi-title'><div class='pbi-title-icon'>"+icon('chart')+"</div><div class='pbi-title-text'><strong>Volume de Logs por Severidade</strong><span>Barras temporais por categoria</span></div></div><div class='pbi-actions'><div class='pbi-refresh'>Atualizado "+lastRefresh+"</div><button class='pbi-insight-btn' id='insight-btn' title='Insight rapido'>"+icon('bulb')+"</button></div><div class='pbi-insight-popover' id='insight-popover'><strong>Insight rapido</strong><span>"+escapeHTML(insightText)+"</span></div></header><section class='pbi-gauge-grid'>"+renderGauge('ok','Normal','--green',normalPct,normalCount,'good','Normal','Info e notice agrupados como eventos normais.','info,notice')+renderGauge('warn','Atencao','--yellow',warnPct,warnCount,warnCount>0?'warn':'good',warnCount>0?'Atencao':'Normal','Eventos warning indicam atencao sem queda critica.','warning')+renderGauge('bad','Critico','--red',critPct,critCount,critCount>0?'bad':'good',critCount>0?'Critico':'Normal','Emerg, alert, crit e err agrupados como eventos criticos.','emerg,alert,crit,err')+"</section><section class='pbi-panel'><div class='pbi-panel-title'><div class='pbi-panel-heading'><strong>Atividade de logs por janela</strong><small>histograma separado por categoria</small></div><div class='pbi-legend'>"+legendHtml+"</div></div><div class='pbi-chart-wrap'></div></section></div>";
renderChart();
var insightBtn=container.querySelector('#insight-btn');
var insightPopover=container.querySelector('#insight-popover');
if(insightBtn&&insightPopover){insightBtn.addEventListener('click',function(ev){ev.stopPropagation();insightPopover.classList.toggle('open');});}
container.addEventListener('click',function(ev){if(!ev.target.closest('.pbi-insight-popover')&&!ev.target.closest('.pbi-insight-btn')){if(insightPopover)insightPopover.classList.remove('open');}});
if(typeof ResizeObserver!=='undefined'){if(container.__logsResizeObserver){container.__logsResizeObserver.disconnect();}var resizeTimer=null;container.__logsResizeObserver=new ResizeObserver(function(){clearTimeout(resizeTimer);resizeTimer=setTimeout(function(){renderChart();},120);});var cw=container.querySelector('.pbi-chart-wrap');if(cw)container.__logsResizeObserver.observe(cw);}
})();

function drillFromGauge(value){
  if(!value) return;
  var url = new URL(window.location.href);
  url.searchParams.delete('var-severity');
  value.split(',').forEach(function(v){ if(v) url.searchParams.append('var-severity', v); });
  window.location.href = url.toString();
}
htmlNode.querySelectorAll('.pbi-gauge-card[data-drill]').forEach(function(card){
  card.addEventListener('click',function(ev){
    if(ev.target.closest('.pbi-gauge-help')) return;
    drillFromGauge(card.getAttribute('data-drill'));
  });
});

options.css:
html, body {
  background-color: #11161d;
  margin: 0;
  padding: 0;
  height: 100%;
  width: 100%;
  font-family: 'Segoe UI', sans-serif;
}
.dashboard-container {
  background-color: #11161d;
  color: #ffffff;
  padding: 0;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.dashboard-head {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 22px;
  padding: 16px 24px;
  background:
    linear-gradient(90deg, rgba(255, 95, 0, 0.12), transparent 24%),
    linear-gradient(135deg, #151a22 0%, #10141b 100%);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 12px;
}
.hdr-left {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
  gap: 18px;
}
.brand-mark {
  width: 92px;
  height: 64px;
  flex: 0 0 92px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: #ff5f00;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.14), 0 10px 28px rgba(255, 95, 0, 0.18);
}
.brand-word {
  color: #ffffff;
  font-size: 26px;
  font-weight: 900;
  line-height: 0.78;
  letter-spacing: 0;
  text-transform: uppercase;
}
.brand-word span {
  display: block;
}
.title-box {
  min-width: 0;
  flex: 1;
  padding: 2px 0 2px 22px;
  border-left: 5px solid #ff5f00;
}
.title-box h1 {
  font-size: clamp(1.05rem, 1.8vw, 1.36rem);
  text-transform: uppercase;
  margin: 0;
  color: #ffffff;
  letter-spacing: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.title-box p {
  font-size: clamp(0.72rem, 1.15vw, 0.82rem);
  color: #d7dde8;
  margin: 8px 0 0;
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.hdr-right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}
.back-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 11px;
  border-radius: 6px;
  border: 1px solid rgba(249, 115, 22, 0.36);
  background: rgba(249, 115, 22, 0.12);
  color: #ffb07a;
  text-decoration: none;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}
.back-btn:hover {
  background: rgba(249, 115, 22, 0.22);
  color: #ffffff;
}
.back-btn svg {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}
.pills {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
  justify-content: flex-end;
}
.pill {
  font-size: 10.5px;
  font-weight: 800;
  padding: 5px 10px;
  border-radius: 6px;
  letter-spacing: 0;
  white-space: nowrap;
  border: 1px solid transparent;
}
.pill-huawei {
  background: rgba(255, 95, 0, 0.12);
  border-color: rgba(255, 95, 0, 0.32);
  color: #ff9b5c;
}
.pill-syslog {
  background: rgba(56, 189, 248, 0.12);
  border-color: rgba(56, 189, 248, 0.32);
  color: #7dd3fc;
}
.pill-loki {
  background: rgba(167, 139, 250, 0.12);
  border-color: rgba(167, 139, 250, 0.32);
  color: #c4b5fd;
}
.pill-otlp {
  background: rgba(34, 197, 94, 0.10);
  border-color: rgba(34, 197, 94, 0.28);
  color: #86efac;
}
.live {
  display: flex;
  align-items: center;
  gap: 7px;
  background: rgba(16, 185, 129, 0.08);
  border: 1px solid rgba(16, 185, 129, 0.22);
  padding: 6px 12px;
  border-radius: 6px;
  white-space: nowrap;
}
.live-dot {
  width: 7px;
  height: 7px;
  background: #10b981;
  border-radius: 50%;
  animation: blink 2s ease-in-out infinite;
  box-shadow: 0 0 8px rgba(16, 185, 129, 0.6);
  flex-shrink: 0;
}
.live-lbl {
  font-size: 11px;
  font-weight: 700;
  color: #10b981;
}
@keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }
@media (max-width: 1000px) {
  .dashboard-head {
    align-items: flex-start;
    flex-direction: column;
    padding: 14px;
  }
  .hdr-right {
    width: 100%;
    justify-content: space-between;
  }
  .pills {
    justify-content: flex-start;
  }
  .title-box h1, .title-box p {
    white-space: normal;
  }
}
@media (max-width: 620px) {
  .hdr-left {
    align-items: flex-start;
    flex-direction: column;
  }
  .brand-mark {
    width: 82px;
    height: 56px;
    flex-basis: 56px;
  }
  .brand-word {
    font-size: 23px;
  }
  .title-box {
    padding-left: 14px;
  }
  .hdr-right {
    align-items: stretch;
    flex-direction: column;
  }
}.svg-icon{display:inline-grid;place-items:center;width:1em;height:1em;line-height:1;vertical-align:-.125em;flex-shrink:0}.svg-icon svg{width:1em;height:1em;display:block}

options.onRender:
(function(){
function withKiosk(url){if(!url){return url;}return /[?&]kiosk(?:[=&]|$)/.test(url)?url:url+(url.indexOf('?')>=0?'&':'?')+'kiosk';}function fallbackUrl(query){return withKiosk('/dashboards?query='+encodeURIComponent(query||''));}
function goByQuery(query,title){
  var fallback=fallbackUrl(query||title);
  if(!query&&!title){window.location.assign('/dashboards?kiosk');return;}
  fetch('/api/search?type=dash-db&query='+encodeURIComponent(query||title),{credentials:'same-origin'})
    .then(function(r){return r.ok?r.json():[];})
    .then(function(items){
      var exact=title?(items||[]).find(function(item){return item.title===title;}):null;
      var found=exact||(items||[])[0];
      window.location.assign(found&&found.url?withKiosk(found.url):fallback);
    })
    .catch(function(){window.location.assign(fallback);});
}
htmlNode.querySelectorAll('[data-dashboard-query]').forEach(function(el){
  el.addEventListener('click',function(ev){
    ev.preventDefault();
    ev.stopPropagation();
    goByQuery(el.getAttribute('data-dashboard-query'),el.getAttribute('data-dashboard-title'));
  });
});
})();

options.css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800;900&family=Roboto+Mono:wght@600;700;900&display=swap');
* { box-sizing: border-box; margin: 0; padding: 0; font-family: 'Inter', sans-serif; }
#kpi2-container {
  width: 100%;
  height: 100%;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  align-items: stretch;
  gap: 12px;
  padding: 12px 10px;
  background: linear-gradient(135deg, #151a22 0%, #10141b 100%);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  overflow: visible;
}
.kpi2-card {
  --accent: #8b949e;
  --accent-soft: rgba(139, 148, 158, 0.12);
  position: relative;
  z-index: 1;
  min-width: 0;
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border-radius: 8px;
  background:
    linear-gradient(135deg, var(--accent-soft), rgba(255, 255, 255, 0.015) 42%),
    #11161d;
  border: 1px solid rgba(255, 255, 255, 0.09);
  box-shadow: inset 4px 0 0 var(--accent);
  overflow: visible;
}
.kpi2-card::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}
.kpi2-icon {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  color: var(--accent);
  background: var(--accent-soft);
  border: 1px solid color-mix(in srgb, var(--accent) 38%, transparent);
  font-size: 18px;
}
.kpi2-content {
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
}
.kpi2-label {
  font-size: 0.67rem;
  font-weight: 900;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi2-value {
  font-family: 'Roboto Mono', monospace;
  font-size: clamp(1.25rem, 2.35vw, 1.72rem);
  font-weight: 900;
  color: #ffffff;
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi2-sub {
  font-size: 0.64rem;
  font-weight: 700;
  color: #8792a2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.c-total {
  --accent: #38bdf8;
  --accent-soft: rgba(56, 189, 248, 0.12);
}
.c-normal {
  --accent: #2ecc71;
  --accent-soft: rgba(46, 204, 113, 0.12);
}
.c-atencao {
  --accent: #facc15;
  --accent-soft: rgba(250, 204, 21, 0.12);
}
.c-critico {
  --accent: #ef4444;
  --accent-soft: rgba(239, 68, 68, 0.12);
}
@supports not (color: color-mix(in srgb, red 50%, transparent)) {
  .kpi2-icon { border-color: rgba(255, 255, 255, 0.16); }
}
@media (max-width: 1100px) {
  #kpi2-container {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 620px) {
  #kpi2-container {
