(function () {
  function valuesToArray(values) {
    if (!values) return [];
    if (Array.isArray(values)) return values;
    if (typeof values.toArray === 'function') return values.toArray();
    var len = values.length || values.size || (values.buffer ? values.buffer.length : 0) || 0;
    var out = [];
    for (var i = 0; i < len; i++) out.push(typeof values.get === 'function' ? values.get(i) : values[i]);
    return out;
  }

  function lastInstantValue(frame) {
    try {
      var f = frame.fields;
      if (!f || f.length < 2) return 0;
      var vals = valuesToArray(f[1].values);
      for (var i = vals.length - 1; i >= 0; i--) {
        var n = Number(vals[i]);
        if (Number.isFinite(n)) return n;
      }
      return 0;
    } catch (e) { return 0; }
  }

  var byRef = {};
  (data && data.series ? data.series : []).forEach(function (s) {
    byRef[s.refId] = lastInstantValue(s);
  });

  var total = Math.round(byRef['A'] || 0);
  var normal = Math.round(byRef['B'] || 0);
  var atencao = Math.round(byRef['C'] || 0);
  var critico = Math.round(byRef['D'] || 0);

  var elTotal = htmlNode.querySelector('#v-total');
  var elNormal = htmlNode.querySelector('#v-normal');
  var elAtencao = htmlNode.querySelector('#v-atencao');
  var elCritico = htmlNode.querySelector('#v-critico');
  if (elTotal) elTotal.textContent = total.toLocaleString('pt-BR');
  if (elNormal) elNormal.textContent = normal.toLocaleString('pt-BR');
  if (elAtencao) elAtencao.textContent = atencao.toLocaleString('pt-BR');
  if (elCritico) elCritico.textContent = critico.toLocaleString('pt-BR');
})();


function drillSeverity(values){
  var url = new URL(window.location.href);
  url.searchParams.delete('var-severity');
  values.forEach(function(v){ url.searchParams.append('var-severity', v); });
  window.location.href = url.toString();
}
[
  ['.c-total',['$__all']],
  ['.c-normal',['info','notice']],
  ['.c-atencao',['warning']],
  ['.c-critico',['emerg','alert','crit','err']]
].forEach(function(item){
  var el = htmlNode.querySelector(item[0]);
  if(!el) return;
  el.title = 'Clique para filtrar por severidade';
  el.onclick = function(ev){
    if(ev.target.closest('.kpi2-info-btn')) return;
    drillSeverity(item[1]);
  };
});

