options.onRender:
(function(){
function valuesToArray(values){if(!values)return[];if(Array.isArray(values))return values;if(typeof values.toArray==='function')return values.toArray();var len=values.length||values.size||(values.buffer?values.buffer.length:0)||0;var out=[];for(var i=0;i<len;i++){out.push(typeof values.get==='function'?values.get(i):values[i]);}return out;}
function esc(v){return String(v==null?'':v).replace(/[&<>]/g,function(c){return c==='&'?'&amp;':(c==='<'?'&lt;':'&gt;');});}
function fieldByName(frame,names){var fields=(frame&&frame.fields)||[];var lowered=names.map(function(n){return String(n).toLowerCase();});for(var i=0;i<fields.length;i++){var f=fields[i];var n1=String(f.name||'').toLowerCase();var n2=String((f.config&&f.config.displayName)||'').toLowerCase();if(lowered.indexOf(n1)!==-1||lowered.indexOf(n2)!==-1)return f;}return null;}
var root=htmlNode.querySelector('#ops-top-switches');if(!root)return;var body=root.querySelector('.ops-body');if(!body)return;
var counts={};
(data&&data.series||[]).forEach(function(frame){
  var field=fieldByName(frame,["Switch","switchname","host"]);
  if(!field)return;
  valuesToArray(field.values).forEach(function(raw){
    var name=String(raw||'').trim();
    if(!name||name==='-'||name==='N/A')return;
    counts[name]=(counts[name]||0)+1;
  });
});
var rows=Object.keys(counts).map(function(name){return{name:name,value:counts[name]};}).sort(function(a,b){return b.value-a.value||a.name.localeCompare(b.name);}).slice(0,5);
if(!rows.length){body.innerHTML="<div class='ops-empty'>Sem switches no periodo.</div>";return;}
body.innerHTML=rows.map(function(r,idx){return "<div class='ops-row'><div class='ops-main'><span class='ops-name'>"+esc(r.name)+"</span><span class='ops-sub'>"+(idx+1)+" - logs por switch</span></div><span class='ops-value'>"+Math.round(r.value).toLocaleString('pt-BR')+"</span></div>";}).join('');
})();

(function(){
var panelNode = htmlNode;
var wrapper = panelNode.querySelector('#legend-cards-wrapper');
var donutChart = panelNode.querySelector('#donut-chart');
var donutTotal = panelNode.querySelector('#donut-total');
if(!wrapper||!donutChart||!donutTotal) return;

var SEV_ORDER = ['emerg','alert','crit','err','warning','notice','info','debug'];
var SEV_META = {
  emerg:{icon:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.1' stroke-linecap='round' stroke-linejoin='round'><path d='M12 3a8 8 0 0 0-8 8c0 3 1.7 5.5 4 6.8V21h8v-3.2c2.3-1.3 4-3.8 4-6.8a8 8 0 0 0-8-8Z'/><circle cx='9' cy='11' r='1'/><circle cx='15' cy='11' r='1'/><path d='M10 16h4'/></svg>",label:'Emerg',border:'border-emerg',color:'color-emerg',hex:'#dc2626'},
  alert:{icon:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><path d='M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9'/><path d='M10 21h4'/></svg>",label:'Alert',border:'border-alert',color:'color-alert',hex:'#e11d48'},
  crit:{icon:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><path d='M8.5 14.5A4.5 4.5 0 0 0 17 12c0-4-4-6-4-9-3 2-6 5-6 10a5 5 0 0 0 10 0'/></svg>",label:'Crit',border:'border-crit',color:'color-crit',hex:'#ef4444'},
  err:{icon:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.4' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='9'/><path d='m15 9-6 6'/><path d='m9 9 6 6'/></svg>",label:'Err',border:'border-err',color:'color-err',hex:'#f97316'},
  warning:{icon:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.3' stroke-linecap='round' stroke-linejoin='round'><path d='M12 3 2.8 19a2 2 0 0 0 1.7 3h15a2 2 0 0 0 1.7-3L12 3Z'/><path d='M12 9v5'/><path d='M12 18h.01'/></svg>",label:'Aviso',border:'border-warning',color:'color-warning',hex:'#eab308'},
  notice:{icon:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.3' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='9'/><path d='M12 11v5'/><path d='M12 8h.01'/></svg>",label:'Notice',border:'border-notice',color:'color-notice',hex:'#0ea5e9'},
  info:{icon:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.5' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='9'/><path d='m8.5 12.5 2.3 2.3 4.9-5.4'/></svg>",label:'Info',border:'border-info',color:'color-info',hex:'#16a34a'},
  debug:{icon:"<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.1' stroke-linecap='round' stroke-linejoin='round'><rect x='8' y='7' width='8' height='12' rx='4'/><path d='M8 11H4'/><path d='M16 11h4'/><path d='M8 15H4'/><path d='M16 15h4'/><path d='m9 4 2 3'/><path d='m15 4-2 3'/></svg>",label:'Debug',border:'border-debug',color:'color-debug',hex:'#64748b'}
};

function valuesToArray(values){
  if(!values) return [];
  if(Array.isArray(values)) return values;
  if(typeof values.toArray==='function') return values.toArray();
  var len = values.length || values.size || (values.buffer?values.buffer.length:0) || 0;
  var out=[];
  for(var i=0;i<len;i++){ out.push(typeof values.get==='function'?values.get(i):values[i]); }
  return out;
}
function lastNumericValue(field){
  var arr = valuesToArray(field && field.values);
  for(var i=arr.length-1;i>=0;i--){
    var v = Number(arr[i]);
    if(Number.isFinite(v)) return v;
  }
  return null;
}
function severityFromText(value){
  var text = String(value || '').toLowerCase();
  var match = text.match(/severity="?([^,"} ]+)"?/);
  if(match) text = match[1];
  for(var i=0;i<SEV_ORDER.length;i++){
    if(text === SEV_ORDER[i] || text.indexOf(SEV_ORDER[i]) !== -1) return SEV_ORDER[i];
  }
  return null;
}
function fieldSeverity(frame, field){
  if(field && field.labels && field.labels.severity) return severityFromText(field.labels.severity);
  var candidates = [
    field && field.config && field.config.displayName,
    field && field.name,
    frame && frame.name,
    frame && frame.refId
  ];
  for(var i=0;i<candidates.length;i++){
    var sv = severityFromText(candidates[i]);
    if(sv) return sv;
  }
  return null;
}
function formatValue(value){
  return Math.round(value).toLocaleString('pt-BR');
}

if(!data || !data.series || data.series.length===0 || data.state!=='Done'){
  wrapper.innerHTML = "<p class='kpi-message'>Aguardando dados...</p>";
  return;
}

var totals = {};
SEV_ORDER.forEach(function(sv){ totals[sv] = 0; });
data.series.forEach(function(frame){
  var fields = (frame && frame.fields) || [];
  var severityFields = fields.filter(function(field){
    var name = String((field && (field.name || (field.config && field.config.displayName))) || '').toLowerCase();
    return name === 'severity' || name === 'sev' || name.indexOf('severity') !== -1;
  });
  fields.forEach(function(field){
    if(!field || field.type === 'time' || /^time$/i.test(field.name || '')) return;
    var values = valuesToArray(field.values);
    var fieldMatched = fieldSeverity(frame, field);
    for(var idx=0; idx<values.length; idx++){
      var val = Number(values[idx]);
      if(!Number.isFinite(val)) continue;
      var matched = fieldMatched;
      if(!matched){
        for(var sidx=0; sidx<severityFields.length; sidx++){
          var sevValues = valuesToArray(severityFields[sidx].values);
          matched = severityFromText(sevValues[idx]);
          if(matched) break;
        }
      }
      if(!matched) continue;
      totals[matched] += val;
    }
  });
});

var grandTotal = SEV_ORDER.reduce(function(sum, sv){ return sum + totals[sv]; }, 0);

wrapper.innerHTML = SEV_ORDER.map(function(sv){
  var meta = SEV_META[sv];
  return "<div class='legend-card " + meta.border + "'>" +
    "<div class='legend-info'><span class='svg-icon " + meta.color + "' aria-hidden='true'>" + meta.icon + "</span><span class='legend-label'>" + meta.label + "</span></div>" +
    "<span class='legend-value'>" + formatValue(totals[sv]) + "</span></div>";
}).join('');

if(grandTotal === 0){
  donutTotal.innerText = "0";
  donutChart.style.background = 'conic-gradient(#30363d 0deg 360deg)';
  return;
}

donutTotal.innerText = formatValue(grandTotal);

var acc = 0;
var stops = [];
SEV_ORDER.forEach(function(sv){
  var val = totals[sv];
  if(val <= 0) return;
  var start = (acc / grandTotal) * 360;
  acc += val;
  var end = (acc / grandTotal) * 360;
  stops.push(SEV_META[sv].hex + ' ' + start.toFixed(2) + 'deg ' + end.toFixed(2) + 'deg');
});
if(acc < grandTotal){
  stops.push('#30363d ' + ((acc/grandTotal)*360).toFixed(2) + 'deg 360deg');
}

donutChart.style.background = 'conic-gradient(' + stops.join(', ') + ')';
})();

(function(){
function escapeHtml(v){return String(v==null?'':v).replace(/[&<>]/g,function(c){return c==='&'?'&amp;':(c==='<'?'&lt;':'&gt;');});}
function normalizeSearchText(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');}
function valuesToArray(values){if(!values)return[];if(Array.isArray(values))return values;if(typeof values.toArray==='function')return values.toArray();var len=values.length||values.size||(values.buffer?values.buffer.length:0)||0;var out=[];for(var i=0;i<len;i++){out.push(typeof values.get==='function'?values.get(i):values[i]);}return out;}
function toMs(v){if(v instanceof Date)return v.getTime();if(typeof v==='number')return v;var p=new Date(v).getTime();return Number.isFinite(p)?p:0;}
function fieldByName(frame,name){var fields=(frame&&frame.fields)||[];var lower=name.toLowerCase();for(var i=0;i<fields.length;i++){var f=fields[i];var n1=String(f.name||'').toLowerCase();var n2=String((f.config&&f.config.displayName)||'').toLowerCase();if(n1===lower||n2===lower)return f;}return null;}
var TABLE_ICON="<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><rect x='3' y='4' width='18' height='16' rx='2'/><path d='M3 10h18'/><path d='M9 4v16'/></svg>";
var SEARCH_ICON="<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.3' stroke-linecap='round' stroke-linejoin='round'><circle cx='11' cy='11' r='7'/><path d='m20 20-3.5-3.5'/></svg>";
var CSV_ICON="<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.1' stroke-linecap='round' stroke-linejoin='round'><path d='M14 2H7a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V7Z'/><path d='M14 2v5h5'/><path d='M8 16h8'/><path d='M8 12h8'/></svg>";
var SEV_ORDER=['emerg','alert','crit','err','warning','notice','info','debug'];
var SEV_META={emerg:{label:'Emerg',cls:'sev-emerg'},alert:{label:'Alert',cls:'sev-alert'},crit:{label:'Crit',cls:'sev-crit'},err:{label:'Err',cls:'sev-err'},warning:{label:'Warn',cls:'sev-warning'},notice:{label:'Notice',cls:'sev-notice'},info:{label:'Info',cls:'sev-info'},debug:{label:'Debug',cls:'sev-debug'}};
var rows=[];
var frame=data&&data.series&&data.series[0];
if(frame){
var timeField=fieldByName(frame,'Hora')||fieldByName(frame,'Time');
var switchField=fieldByName(frame,'Switch');
var sevField=fieldByName(frame,'Sev');
var eventoField=fieldByName(frame,'Evento');
var msgField=fieldByName(frame,'Mensagem');
var times=timeField?valuesToArray(timeField.values):[];
var switches=switchField?valuesToArray(switchField.values):[];
var sevs=sevField?valuesToArray(sevField.values):[];
var eventos=eventoField?valuesToArray(eventoField.values):[];
var msgs=msgField?valuesToArray(msgField.values):[];
var n=times.length;
for(var i=0;i<n;i++){
var sevRaw=String(sevs[i]||'').toLowerCase();
rows.push({time:toMs(times[i]),host:String(switches[i]||'N/A'),severity:SEV_META[sevRaw]?sevRaw:'debug',evento:String(eventos[i]||'-'),mensagem:String(msgs[i]||'-')});
}
}
window.__logPanelState=window.__logPanelState||{activeSeverity:'all',searchTerm:'',currentPage:1};
var state=window.__logPanelState;
var itemsPerPage=15;
var debounceTimer=null;
var rightContainer=htmlNode.querySelector('#log-problems-container');
function formatAge(ms){if(!ms)return '-';var diff=Math.floor((Date.now()-ms)/1000);if(diff<60)return Math.max(0,diff)+'s atras';if(diff<3600)return Math.floor(diff/60)+'m atras';if(diff<86400)return Math.floor(diff/3600)+'h atras';return Math.floor(diff/86400)+'d atras';}
function formatHora(ms){if(!ms)return '-';var d=new Date(ms);return d.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})+' '+d.toLocaleTimeString('pt-BR');}
function exportCsv(list){var Q=String.fromCharCode(34);var esc=function(v){v=String(v==null?'':v).split(Q).join(Q+Q);return Q+v+Q;};var header=[esc('Switch'),esc('Sev'),esc('Evento'),esc('Mensagem'),esc('Hora')].join(';');var lines=[header];list.forEach(function(r){lines.push([esc(r.host),esc(r.severity),esc(r.evento),esc(r.mensagem),esc(formatHora(r.time))].join(';'));});var csv=String.fromCharCode(65279)+lines.join(String.fromCharCode(13,10));var blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='logs-switches-'+Date.now()+'.csv';document.body.appendChild(a);a.click();document.body.removeChild(a);setTimeout(function(){URL.revokeObjectURL(url);},1000);}
function renderRightPanel(){
if(!rightContainer)return;
var filtered=rows.filter(function(r){
if(state.activeSeverity!=='all'&&r.severity!==state.activeSeverity)return false;
if(state.searchTerm){var s=normalizeSearchText(state.searchTerm);var hay=normalizeSearchText(r.host+' '+r.evento+' '+r.mensagem);if(hay.indexOf(s)===-1)return false;}
return true;
});
filtered.sort(function(a,b){return b.time-a.time;});
var totalPages=Math.max(1,Math.ceil(filtered.length/itemsPerPage));
if(state.currentPage>totalPages)state.currentPage=totalPages;
if(state.currentPage<1)state.currentPage=1;
var start=(state.currentPage-1)*itemsPerPage;
var pageItems=filtered.slice(start,start+itemsPerPage);
var rowsHtml='';
pageItems.forEach(function(r){
var meta=SEV_META[r.severity];
var rowClass=(r.severity==='emerg'||r.severity==='alert'||r.severity==='crit'||r.severity==='err')?'row-crit':(r.severity==='warning'?'row-warning':'');
rowsHtml+="<tr class='"+rowClass+"'><td class='cell-host'>"+escapeHtml(r.host)+"</td><td><span class='severity-badge "+meta.cls+"'>"+escapeHtml(r.severity)+"</span></td><td>"+escapeHtml(r.evento)+"</td><td class='cell-problem'><div class='cell-problem-wrap'><span class='cell-problem-text'>"+escapeHtml(r.mensagem)+"</span><button class='copy-log-btn' type='button' title='Copiar mensagem' data-copy='"+escapeHtml(r.mensagem)+"'>"+CSV_ICON+"</button></div></td><td>"+formatAge(r.time)+"</td><td>"+formatHora(r.time)+"</td></tr>";
});
if(!rowsHtml){
rowsHtml="<tr class='problems-empty-row'><td colspan='6'>Nenhum log encontrado para os filtros selecionados.</td></tr>";
}
var filterButtonsHtml="<button class='filter-btn filter-btn-severity "+(state.activeSeverity==='all'?'active':'')+"' data-sev='all' type='button'>All</button>";
filterButtonsHtml+=SEV_ORDER.map(function(sv){
var meta=SEV_META[sv];
return "<button class='filter-btn filter-btn-severity btn-"+sv+" "+(state.activeSeverity===sv?'active':'')+"' data-sev='"+sv+"' type='button'>"+meta.label+"</button>";
}).join('');
rightContainer.innerHTML =
"<div class='log-section-header'><div class='log-section-header-left'><span class='log-section-icon'><span class='svg-icon' aria-hidden='true'>"+TABLE_ICON+"</span></span><div><div class='log-section-title'>Logs dos Switches</div><div class='log-section-sub'>Busca detalhada por switch e severidade</div></div></div></div>"+
"<div class='problems-table-panel'>"+
"<div class='filter-bar'>"+
"<div class='filter-group'><span class='filter-label'>Severidade:</span>"+filterButtonsHtml+"</div>"+
"<div class='search-bar-group'>"+
"<div class='search-input-wrapper'><span class='svg-icon' aria-hidden='true'>"+SEARCH_ICON+"</span>"+
"<input type='text' id='problem-search-input' class='search-input' placeholder='Buscar switch ou evento...' value='"+escapeHtml(state.searchTerm)+"'/></div>"+
"<button class='pagination-btn export-btn' id='btn-export' type='button' title='Exportar CSV'><span class='svg-icon' aria-hidden='true'>"+CSV_ICON+"</span></button>"+
"</div></div>"+
"<div class='table-wrapper'><table class='problems-table'><thead><tr><th>Switch</th><th>Sev</th><th>Evento</th><th>Mensagem</th><th>Idade</th><th>Hora</th></tr></thead><tbody>"+rowsHtml+"</tbody></table></div>"+
"<div class='pagination-controls'><span class='pagination-info'>Pagina "+state.currentPage+" de "+totalPages+" &middot; "+filtered.length+" log(s)</span>"+
"<div class='pagination-buttons'>"+
"<button class='pagination-btn' id='btn-prev' type='button' "+(state.currentPage===1?'disabled':'')+">Anterior</button>"+
"<button class='pagination-btn' id='btn-next' type='button' "+(state.currentPage===totalPages?'disabled':'')+">Proxima</button>"+
"</div></div></div>";
var searchInput=rightContainer.querySelector('#problem-search-input');
if(searchInput){
searchInput.oninput=function(ev){
var value=ev.target.value;
clearTimeout(debounceTimer);
debounceTimer=setTimeout(function(){
state.searchTerm=value;
state.currentPage=1;
renderRightPanel();
var updated=rightContainer.querySelector('#problem-search-input');
if(updated){updated.focus();updated.setSelectionRange(value.length,value.length);}
},400);
};
}
var sevButtons=rightContainer.querySelectorAll('.filter-btn-severity');
for(var i=0;i<sevButtons.length;i++){
(function(btn){
btn.onclick=function(){
state.activeSeverity=btn.getAttribute('data-sev')||'all';
state.currentPage=1;
renderRightPanel();
};
})(sevButtons[i]);
}
var prevBtn=rightContainer.querySelector('#btn-prev');
if(prevBtn){prevBtn.onclick=function(){if(state.currentPage>1){state.currentPage-=1;renderRightPanel();}};}
var nextBtn=rightContainer.querySelector('#btn-next');
if(nextBtn){nextBtn.onclick=function(){if(state.currentPage<totalPages){state.currentPage+=1;renderRightPanel();}};}
var exportBtn=rightContainer.querySelector('#btn-export');
if(exportBtn){exportBtn.onclick=function(){exportCsv(filtered);};}
var copyButtons=rightContainer.querySelectorAll('.copy-log-btn');
for(var ci=0;ci<copyButtons.length;ci++){
(function(btn){btn.onclick=function(){var text=btn.getAttribute('data-copy')||'';if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text);}btn.classList.add('copied');setTimeout(function(){btn.classList.remove('copied');},900);};})(copyButtons[ci]);
}
}
renderRightPanel();
})();
